# -*- coding: utf-8 -*-
"""Рядок 5244: чи піднімає ранг нагоди одяг руху в пулі «йога зранку» (нагода «спорт» без числа ошатності).
Каталог → міст `запити` на `стенд_вх` + повний каталог; пул руки 1. Контроль — робота й побачення (смуга названа):
слоти, пул, бюджет, доза «на межі» мають лишитись. «Рух» = ошатність типу перетинає смугу 1–2 (`інтервал_формальності`).
Запуск із теки `джерела`: python3 проби/пул_нагода_ранг_5244.py"""
import sys, os, json, collections
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(sys.path[0])
import bridge as B, feed as Ф, формальність as ФО
КАТ, База = Ф.каталог_на_диску("каталог_повний.xml"), json.load(open("стенд_вх.json", encoding="utf-8"))
СІДИ = {"ж2 йога зранку": (1, 2, 3, 4)}   # йога — середнє по сідах: частка речей у слоті коливається від сіда
СЦЕНИ = {"ж2 йога зранку": (dict(нагода="спорт", година=8), dict(нагода="спорт", година=8)),
         "робота 09:00 +18": (База["сценарій"], dict(ошатність=[5, 6])),
         "побачення 19:00 дощ": (dict(нагода="побачення", місце="ресторан_районний", дрес_код="smart_casual", година=19, темп_c=18, опади="дощ"), dict(ошатність=[4, 6]))}
рух = lambda x: (lambda i: i[0] is not None and i[0] <= 2)(ФО.інтервал_формальності({"тип": x.get("тип"), "формальність_фото": x.get("формальність_фото")}))
for н, (сц, пасп) in СЦЕНИ.items():
    Л, ЗБ = collections.Counter(), []
    for сід in СІДИ.get(н, (База.get("сід"),)):
        r = json.loads(B.виклик("запити", json.dumps(dict(База, сід=сід, каталог=КАТ, сценарій=сц, паспорт=dict(пасп, **{к: сц[к] for к in ("темп_c", "місце", "година", "опади", "дрес_код") if к in сц}), випадок=н), ensure_ascii=False)))
        к, ст = r["кандидати"], r["стеля"]; ск = lambda т: sum(1 for в in к.values() for x in в if x.get("тип") in т)
        Л.update(речей=r["пул_речей"], символів=ст.get("пул_токенів"), межа=sum(1 for в in к.values() for x in в if x.get("гілка") == "на межі"), кросівки_кеди=ск(("кросівки", "кеди")), легінси=ск(("легінси",)),
                 лофери=ск(("лофери",)), пальта=ск(("пальто",)), сукні=len(к.get("сукня") or []), **{"рух_" + с: sum(map(рух, к.get(с) or [])) for с in ("верх", "низ", "взуття", "верхній_шар")})
        ЗБ.append(({с: len(v) for с, v in к.items()}, ст.get("бюджет")))
    n = len(ЗБ); print("\n%s (сідів %d, середнє): слотів %d, бюджет %s, слоти/сід %s" % (н, n, len(ЗБ[0][0]), ЗБ[0][1], "однакові" if all(z == ЗБ[0] for z in ЗБ) else "РІЗНІ"))
    print("  " + ", ".join("%s %.1f" % (k, v / n) for k, v in Л.items()))
